 if line.split(':')[0] in ('MemTotal','MemAvailable','SwapFree'):out['memory'][line.split(':')[0]]=line.split(':',1)[1].strip()
d=shutil.disk_usage(R);out['disk_bytes']={'total':d.total,'free':d.free}
