for p in sorted(R.glob('preparation/*saved_continuation*')):
 if p.is_dir():
  out['continuation_preparation'].append({'path':str(p),'files':[{'name':x.name,'bytes':x.stat().st_size} for x in p.iterdir() if x.is_file()]})
for pid in pathlib.Path('/proc').iterdir():
 if not pid.name.isdigit():continue
 try:
  a=(pid/'cmdline').read_bytes().split(b'\0');ss=[x.decode(errors='replace') for x in a]
  scripts=[x for x in ss if x.startswith(str(R)) and x.endswith(('.py','.sh'))]
  if scripts:
   st=(pid/'stat').read_text().split();out['project_processes'].append({'pid':int(pid.name),'ppid':int(st[3]),'pgid':int(st[4]),'comm':(pid/'comm').read_text().strip(),'project_script_paths_only':scripts})
 except (OSError,ValueError):pass
for pat in ('/tmp/openh3*.lock','/tmp/h3*.lock',str(R/'*.lock')):
 for q in glob.glob(pat):
  p=pathlib.Path(q);st=p.stat();out['lock_files'].append({'path':q,'inode':st.st_ino,'device':st.st_dev,'size':st.st_size,'existence_is_not_held_lock_proof':True})
print(json.dumps(out,sort_keys=True))

